static long compressTimeBucket(long timeBucket, int dayStep) {
    if (dayStep <= 0) {
        throw new IllegalArgumentException("dayStep must be greater than 0");
    }
    long year = timeBucket / 10000;
    long month = (timeBucket / 100) % 100;
    long day = timeBucket % 100;

    if (dayStep == 1) {
        return timeBucket;
    } else if (dayStep == 7) {
        day = (day - 1) / 7 * 7 + 1;
    } else if (dayStep == 11) {
        if (day <= 5) {
            day = 1;
        } else if (day <= 15) {
            day = 12;
        } else if (day <= 25) {
            day = 23;
        } else {
            day = 30;
        }
    } else {
        throw new IllegalArgumentException("Unsupported dayStep value");
    }

    return year * 10000 + month * 100 + day;
}

