int addConstantNameAndType(final String name, final String descriptor) {
    // Check if the constant pool already contains a similar item
    for (int i = 0; i < constantPool.size(); i++) {
        if (constantPool.get(i) instanceof ConstantNameAndType_info) {
            ConstantNameAndType_info info = (ConstantNameAndType_info) constantPool.get(i);
            if (info.getName().equals(name) && info.getDescriptor().equals(descriptor)) {
                return i; // Return the existing index
            }
        }
    }
    // Create a new CONSTANT_NameAndType_info and add it to the constant pool
    ConstantNameAndType_info newInfo = new ConstantNameAndType_info(name, descriptor);
    constantPool.add(newInfo);
    return constantPool.size() - 1; // Return the new index
}

